package fraymus.workspace;

import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Durable actual native trials, immutable decisions and reversible explicit activation. */
final class PoseStudyStore implements AutoCloseable {
    private final Path root,file;private final LinkedHashMap<String,JSONObject> jobs=new LinkedHashMap<>();
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"native-pose-evaluation");t.setDaemon(true);return t;});private volatile boolean closed,stop;private volatile String active="";private volatile PoseStore nativeOwner;
    PoseStudyStore(Path project) throws Exception {root=project.resolve("pose-evaluation");file=root.resolve("state.json");if(Files.exists(file)){var state=new JSONObject(Files.readString(file));for(Object raw:state.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("running"))j.put("status","interrupted").put("reason","Process ended; explicit Resume continues the frozen native trial and completed evidence");jobs.put(j.getString("id"),j);}}persist();}
    private synchronized void persist() throws Exception {atomic(file,new JSONObject().put("jobs",new JSONArray(jobs.values())));}
    static void atomic(Path path,JSONObject data) throws Exception {Files.createDirectories(path.getParent());var pending=path.resolveSibling(path.getFileName()+".pending");Files.writeString(pending,data.toString(),StandardCharsets.UTF_8);Files.move(pending,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    synchronized boolean busy(){return !active.isEmpty();}
    synchronized JSONObject read(String id){var j=jobs.get(id);if(j==null)throw new IllegalArgumentException("Unknown pose-evaluation job");return PushLearning.copy(j);}
    synchronized String status(String id){return jobs.get(id).getString("status");}
    synchronized JSONObject state(){var list=new JSONArray();for(var j:jobs.values())list.put(new JSONObject().put("id",j.getString("id")).put("status",j.getString("status")).put("completedTrials",j.getJSONArray("trials").length()).put("decision",j.optJSONObject("decision",new JSONObject())));return new JSONObject().put("jobs",list);}
    private Path folder(String id){UUID.fromString(id);return root.resolve("jobs").resolve(id);}
    private void compatible(JSONObject j){if(!j.getString("codeSha256").equals(PoseStudy.identity())||!j.getString("suiteSha256").equals(PushLearning.hash(PoseStudy.suite()))||!j.getJSONObject("suite").similar(PoseStudy.suite()))throw new IllegalStateException("Frozen learning suite/code changed; no replacement experiment started");}
    synchronized JSONObject start(String id,String goalId) throws Exception {if(jobs.containsKey(id))return read(id);if(closed||busy()||jobs.size()>=12)throw new IllegalStateException("Pose comparison owner must be idle with history capacity");UUID.fromString(id);var suite=PoseStudy.suite();var j=new JSONObject().put("id",id).put("goalId",goalId).put("suite",suite).put("suiteSha256",PushLearning.hash(suite)).put("codeSha256",PoseStudy.identity()).put("status","running").put("createdAt",Instant.now()).put("trials",new JSONArray()).put("events",new JSONArray()).put("resumes",0);jobs.put(id,j);active=id;stop=false;persist();worker.submit(()->execute(id));return read(id);}
    synchronized JSONObject resume(String id) throws Exception {if(closed||busy())throw new IllegalStateException("Pose comparison owner must be idle");var j=jobs.get(id);compatible(j);if(!j.getString("status").equals("interrupted")||j.optInt("resumes")>=3)throw new IllegalStateException("Resume an interrupted compatible learning job");j.put("resumes",j.getInt("resumes")+1).put("status","running");active=id;stop=false;persist();worker.submit(()->execute(id));return read(id);}
    synchronized JSONObject cancel(String id) throws Exception {var j=jobs.get(id);if(id.equals(active))stop=true;else if(j.getString("status").equals("interrupted"))j.put("status","cancelled");persist();return read(id);}
    private void execute(String id){try{JSONObject j;synchronized(this){j=jobs.get(id);compatible(j);}
        var suite=j.getJSONObject("suite");for(Object raw:PushLearning.cases(suite,"development")){trial(j,(JSONObject)raw,"baseline",((JSONObject)raw).getDouble("forceLimitN"));trial(j,(JSONObject)raw,"candidate",((JSONObject)raw).getDouble("forceLimitN"));}
        synchronized(this){if(!j.has("candidateFrozenCodeSha256")){j.put("candidateFrozenCodeSha256",PoseCheckpoint.identity()).put("candidateFrozenAfterTrial",j.getJSONArray("trials").length()).put("candidateFrozenAt",Instant.now());persist();}}
        for(Object raw:PushLearning.cases(suite,"evaluation")){var c=(JSONObject)raw;trial(j,c,"baseline",c.getDouble("forceLimitN"));trial(j,c,"candidate",c.getDouble("forceLimitN"));}
        synchronized(this){if(stop||closed)throw new InterruptedException();var verified=verify(id);j.put("decision",verified).put("status","completed").put("completedAt",Instant.now());persist();}
    }catch(Exception e){synchronized(this){var j=jobs.get(id);j.put("status",stop?"cancelled":"interrupted").put("reason",String.valueOf(e.getMessage()));try{persist();}catch(Exception ignored){}}}finally{synchronized(this){active="";}}}
    private void trial(JSONObject j,JSONObject c,String arm,double force) throws Exception {
        if(stop||closed||Thread.currentThread().isInterrupted())throw new InterruptedException("Native pose comparison stopped");String key=c.getString("id")+":"+arm+":"+force;String job=j.getString("id"),runId=UUID.nameUUIDFromBytes((job+":"+key).getBytes(StandardCharsets.UTF_8)).toString();Path dir=folder(job).resolve("native").resolve(runId);JSONObject plan=PoseStudy.plan(c,job);if(!plan.getBoolean("passed"))throw new IllegalStateException("Frozen case has no admitted standing plan: "+c.getString("id"));
        synchronized(this){for(Object raw:j.getJSONArray("trials"))if(((JSONObject)raw).getString("key").equals(key))return;j.put("current",new JSONObject().put("caseId",c.getString("id")).put("split",c.getString("split")).put("arm",arm).put("initialForceN",force).put("runId",runId));persist();}
        try(var nativeStore=new PoseStore(dir)){nativeOwner=nativeStore;
            if(!nativeStore.hasRun(runId))nativeStore.start(runId,j.getString("goalId"),PoseStudy.source(c,job),plan,false,arm.equals("candidate"));
            else if(Set.of("paused","interrupted").contains(nativeStore.status(runId)))nativeStore.resume(runId,PoseStudy.source(c,job),false);
            while(nativeStore.status(runId).equals("running")){if(stop||closed||Thread.currentThread().isInterrupted()){nativeStore.cancel(runId);throw new InterruptedException("Native pose comparison interrupted");}Thread.sleep(5);}
            var run=nativeStore.run(runId);if(!Set.of("completed","failed").contains(run.getString("status")))throw new IllegalStateException("Native trial stopped: "+run.optString("reason"));var metrics=PoseVerify.verify(run);Path result=dir.resolve("result.json");atomic(result,run);String rawSha=MapDefinition.sha(Files.readAllBytes(result));
            synchronized(this){if(stop||closed)throw new InterruptedException();j.getJSONArray("trials").put(new JSONObject().put("key",key).put("caseId",c.getString("id")).put("split",c.getString("split")).put("arm",arm).put("initialForceN",force).put("runId",runId).put("rawSha256",rawSha).put("nativeStatus",run.getString("status")).put("reason",run.optString("reason","")).put("metrics",metrics));j.getJSONArray("events").put(new JSONObject().put("kind","trial-completed").put("ordinal",j.getJSONArray("trials").length()).put("caseId",c.getString("id")).put("arm",arm));persist();}
        }
    }
    synchronized JSONObject live(){if(active.isEmpty()||nativeOwner==null)return new JSONObject();var j=jobs.get(active);var c=j.optJSONObject("current");if(c==null)return new JSONObject();var snapshot=nativeOwner.snapshot();if(!snapshot.optString("id").equals(c.getString("runId")))return new JSONObject();var scene=PoseStudy.source(PushLearning.find(j.getJSONObject("suite"),c.getString("caseId")),active);return new JSONObject().put("source",scene).put("currentTrial",c).put("snapshot",snapshot);}
    synchronized JSONObject nativeRun(String id,String runId) throws Exception {UUID.fromString(runId);var j=read(id);for(Object raw:j.getJSONArray("trials"))if(((JSONObject)raw).getString("runId").equals(runId)){var t=(JSONObject)raw;Path path=folder(id).resolve("native").resolve(runId).resolve("result.json");if(!MapDefinition.sha(Files.readAllBytes(path)).equals(t.getString("rawSha256")))throw new IllegalStateException("Original native trial bytes changed");return new JSONObject(Files.readString(path));}throw new IllegalArgumentException("Native trial not committed");}
    synchronized JSONObject verify(String id) throws Exception {
        var j=jobs.get(id);compatible(j);var suite=j.getJSONObject("suite");var rows=j.getJSONArray("trials");int development=2*PushLearning.cases(suite,"development").length();if(j.getInt("candidateFrozenAfterTrial")!=development||!j.getString("candidateFrozenCodeSha256").equals(PoseCheckpoint.identity())||rows.length()!=2*suite.getJSONArray("cases").length())throw new IllegalStateException("Original code pin/split/count changed");var seen=new java.util.HashSet<String>();
        for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);if(!seen.add(row.getString("key"))||(i<development)!=row.getString("split").equals("development"))throw new IllegalStateException("Reserved chronology changed");var c=PushLearning.find(suite,row.getString("caseId"));if(!c.getString("split").equals(row.getString("split"))||row.getDouble("initialForceN")!=c.getDouble("forceLimitN"))throw new IllegalStateException("Original case/force changed");var run=nativeRun(id,row.getString("runId"));boolean candidate=row.getString("arm").equals("candidate");if(!run.getString("goalId").equals(j.getString("goalId"))||!run.getJSONObject("definition").similar(PoseStudy.source(c,id))||!run.getJSONObject("plan").similar(PoseStudy.plan(c,id))||!PoseVerify.verify(run).similar(row.getJSONObject("metrics"))||candidate!=run.getBoolean("orientationControl"))throw new IllegalStateException("Original native controller/source/ledger changed");}
        return PoseStudy.decide(suite,rows);
    }

    @Override public void close(){closed=true;worker.shutdownNow();try{worker.awaitTermination(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
